import type { CareGuide, DisciplineId } from "./care-guides"

export type TopicEducation = { signs: string; evaluation: string; preparation: string; followup: string }
type Topic = {
  parent: string; slug: string; focus: string; overview: string; audience: string;
  education: TopicEducation; care: [string, string, string, string, string, string]; urgent: string; contact: string;
  source: [string, string]; extra?: { title: string; organization: string; url: string }[];
}

export const additionalTopics: Topic[] = [
  { parent: "cardiologia", slug: "insuficiencia-cardiaca", focus: "Insuficiencia cardíaca", audience: "Personas adultas con insuficiencia cardíaca estable y su red de apoyo.", overview: "El corazón puede tener dificultad para llenarse o bombear sangre de forma eficaz. Los síntomas, la causa y el tipo de insuficiencia orientan el tratamiento; un cambio rápido puede anunciar descompensación.", education: { signs: "Observa si necesitas más almohadas para respirar, aparece edema o disminuye tu tolerancia al caminar. El cansancio aislado no permite confirmar el diagnóstico.", evaluation: "La exploración, el electrocardiograma, los análisis y el ecocardiograma ayudan a conocer función cardíaca y causas. Cada prueba responde una pregunta diferente.", preparation: "Lleva tu registro de peso si se indicó, la lista completa de fármacos y los síntomas nuevos. Solicita un plan de acción escrito.", followup: "Pregunta qué cambio de peso o síntomas requiere aviso y cuándo revisar presión, riñón y electrolitos. No cambies diuréticos por una cifra aislada." }, care: ["Si se indicó pesarte, usa condiciones similares y registra tendencia y síntomas.|Observa tobillos, respiración y tolerancia a tus actividades.|Pide ayuda para medir sin riesgo de caída.", "Conoce tu tipo de insuficiencia y el objetivo de cada tratamiento.|Acordar un plan de descompensación permite actuar antes de empeorar.|Consulta por rehabilitación cardíaca si estás estable.", "Revisa cómo tomar diuréticos y qué hacer ante una dosis olvidada.|No aumentes dosis ni suspendas fármacos por tu cuenta.|Consulta antes de antiinflamatorios o preparados con sodio.", "La sal y los líquidos se individualizan según congestión y función renal.|Compara etiquetas y evita añadir sal por costumbre.|Informa falta de apetito o pérdida de peso no buscada.", "Realiza ejercicio progresivo dentro de tu capacidad y plan autorizado.|Alterna actividad con descansos y evita esfuerzo en una descompensación.|Interrumpe la actividad si aparece dolor torácico o mareo.", "Planifica tareas en momentos de mayor energía.|Habla del temor a la falta de aire y del apoyo que necesitas.|Solicita atención si ansiedad o tristeza dificultan el autocuidado."], urgent: "Falta de aire intensa en reposo, dolor de pecho, desmayo o confusión nueva: activa emergencias.", contact: "Más hinchazón, necesidad de dormir incorporado o cambios de peso fuera de tu plan: avisa pronto al equipo.", source: ["Fallo cardíaco", "heartfailure.html"] },
  { parent: "endocrinologia", slug: "hipotiroidismo", focus: "Hipotiroidismo", audience: "Personas con hipotiroidismo confirmado; embarazo y recién nacidos requieren un seguimiento diferente.", overview: "La tiroides produce menos hormona de la necesaria. Puede causar síntomas graduales y se confirma con análisis; la dosis de sustitución hormonal necesita ajustes supervisados.", education: { signs: "Cansancio, frío, estreñimiento o piel seca pueden aparecer, pero también tienen otras causas. No ajustes medicación solo por estos síntomas.", evaluation: "TSH y, según el caso, tiroxina libre ayudan a valorar función y respuesta. Informa suplementos que puedan alterar análisis.", preparation: "Lleva el nombre y horario de tu medicamento, suplementos y resultados previos. Informa si planeas embarazo o ya estás embarazada.", followup: "El control tras iniciar o modificar tratamiento se programa por el equipo. La mejoría puede ser progresiva y no exige duplicar dosis." }, care: ["Registra síntomas que limitan tu rutina y el horario de la toma.|Usa recordatorios para mantener regularidad.|Informa palpitaciones o temblor nuevos.", "Revisa los análisis y el objetivo individual, no solo una cifra de internet.|El embarazo puede cambiar las necesidades de hormona: avisa pronto.|Consulta antes de suspender controles porque te sientes bien.", "Confirma cómo tomar levotiroxina respecto a comidas y otros medicamentos.|Hierro, calcio y antiácidos pueden interferir: acuerda separación de tomas.|No uses hormona tiroidea para adelgazar.", "Mantén alimentación variada y consulta medidas para estreñimiento.|No empieces yodo, algas o suplementos tiroideos sin valoración.|No se necesita eliminar todos los alimentos con soya o gluten sin indicación.", "Retoma actividad gradualmente si el cansancio lo permite.|Con síntomas intensos o cardiopatía, acuerda primero la intensidad.|No se requiere una rutina de fisioterapia para corregir la hormona.", "Habla del impacto de fatiga o lentitud en tu ánimo.|Evita interpretar las dificultades como falta de voluntad.|Pide evaluación si la tristeza persiste aunque el control hormonal mejore."], urgent: "Somnolencia extrema, confusión, respiración lenta o desmayo: atención inmediata.", contact: "Síntomas persistentes, embarazo, palpitaciones o efectos tras cambiar tratamiento.", source: ["Hipotiroidismo", "hypothyroidism.html"] },
  { parent: "neumologia", slug: "epoc", focus: "Enfermedad pulmonar obstructiva crónica (EPOC)", audience: "Personas con EPOC confirmada y cuidadores; no sustituye la atención de una exacerbación.", overview: "La EPOC dificulta el paso de aire y puede reducir la tolerancia al esfuerzo. Dejar el tabaco, revisar inhaladores y reconocer un empeoramiento son partes esenciales del cuidado.", education: { signs: "Compara tu respiración, tos y secreciones con lo habitual. Mayor falta de aire o cambios de esputo pueden indicar una exacerbación.", evaluation: "La espirometría ayuda a confirmar obstrucción. El equipo valora síntomas, exacerbaciones previas y necesidad real de oxígeno.", preparation: "Lleva tus inhaladores para demostrar la técnica y solicita un plan para empeoramientos. Informa humo y exposiciones del hogar o trabajo.", followup: "Revisa vacunas, nutrición, técnica y acceso a rehabilitación pulmonar. Tener oxígeno no autoriza a cambiar el flujo sin indicación." }, care: ["Practica la técnica de inhalación con el dispositivo concreto que utilizas.|Registra cambios respecto a tu respiración habitual.|Mantén oxígeno lejos de tabaco, llamas y fuentes de calor.", "Pide apoyo para dejar el tabaco y revisar vacunas apropiadas.|Conoce cuándo consultar por exacerbación y dónde acudir.|No todas las personas necesitan antibióticos u oxígeno.", "Distingue tratamiento de mantenimiento y alivio según tu plan.|Revisa limpieza, dosis disponibles y posibles interacciones.|No inicies corticoides o antibióticos salvo pauta escrita individual.", "Si comer te cansa, distribuye comidas en porciones tolerables.|Informa pérdida de peso o debilidad para ajustar energía y proteína.|Evita restricciones que empeoren desnutrición.", "Solicita rehabilitación pulmonar para ejercicio y conservación de energía.|Aprende respiración con labios fruncidos si te la indican.|Una dificultad respiratoria grave requiere ayuda, no solo ejercicios.", "La falta de aire puede generar miedo: prepara una estrategia con tu equipo.|Mantén actividades sociales adaptadas y solicita apoyo.|La ansiedad no descarta un empeoramiento pulmonar."], urgent: "Dificultad para hablar por falta de aire, color azulado, somnolencia o confusión: emergencia.", contact: "Más tos, fiebre, cambios del esputo o menor capacidad para tus actividades.", source: ["EPOC", "copd.html"] },
  { parent: "neurologia", slug: "epilepsia", focus: "Epilepsia y seguridad ante convulsiones", audience: "Personas con epilepsia y quienes pueden presenciar una crisis.", overview: "Las crisis se deben a actividad eléctrica cerebral anormal y no siempre producen movimientos intensos. El tratamiento y los primeros auxilios se adaptan al tipo de crisis.", education: { signs: "Puede haber desconexión, sensaciones inusuales o convulsiones. Describe lo observado sin asumir que todo desmayo es epilepsia.", evaluation: "La historia de los episodios, el EEG y, cuando corresponde, imágenes ayudan a clasificar la causa. Un EEG normal no excluye todas las crisis.", preparation: "Acuerda un plan de rescate, contactos y medidas de seguridad en baño, agua, alturas y trabajo. Enseña el plan a alguien de confianza.", followup: "Registra duración y recuperación; lleva las dudas sobre conducción, embarazo y efectos de medicamentos. No retires antiepilépticos de golpe." }, care: ["Durante una convulsión protege la cabeza, retira peligros y cuenta el tiempo.|No sujetes a la persona ni introduzcas nada en la boca.|Cuando sea seguro, colócala de lado y acompaña la recuperación.", "Solicita un plan escrito que indique cuándo usar rescate y activar emergencias.|Revisa sueño, desencadenantes y restricciones de conducción con tu equipo.|La primera convulsión necesita valoración médica.", "Mantén horarios y consulta antes de cambiar o suspender antiepilépticos.|Verifica interacciones y anticoncepción si corresponde.|El medicamento de rescate requiere enseñanza de su dispositivo y pauta.", "No se necesita una dieta cetogénica de rutina.|Las dietas terapéuticas para epilepsia requieren seguimiento especializado.|No ofrezcas alimentos ni líquidos hasta recuperar plenamente la alerta.", "El ejercicio puede adaptarse al control de crisis y al riesgo de la actividad.|No nades solo ni practiques actividades peligrosas sin valoración.|No se realiza fisioterapia para detener una convulsión.", "Habla del estigma y del miedo a nuevas crisis.|Prepara apoyos para escuela, trabajo y vida social.|Evita culpar a la persona por crisis que ocurran pese al tratamiento."], urgent: "Convulsión de 5 minutos o más, crisis repetidas sin recuperación, lesión grave o dificultad respiratoria: emergencias; sigue también tu plan individual.", contact: "Aumento de crisis, efectos adversos o cambios en embarazo y planificación reproductiva.", source: ["Epilepsia", "epilepsy.html"] },
  { parent: "nefrologia", slug: "hemodialisis", focus: "Hemodiálisis y cuidado del acceso vascular", audience: "Personas que reciben hemodiálisis; una fístula y un catéter requieren cuidados distintos.", overview: "La hemodiálisis retira desechos y exceso de líquido mediante un circuito externo. El acceso vascular permite realizarla y debe protegerse de lesiones e infecciones.", education: { signs: "Observa fiebre, sangrado, dolor o cambios del acceso. Si tienes fístula, aprende cómo reconocer su vibración habitual.", evaluation: "Los análisis y la valoración del peso y los síntomas ayudan a ajustar la diálisis. El peso objetivo no se determina por apariencia.", preparation: "Conoce tu calendario, transporte y contacto para incidencias. Pide instrucciones escritas para acceso, medicamentos y alimentación.", followup: "No faltes a sesiones por sentirte bien; si no puedes acudir o el acceso cambia, llama al centro para organizar atención." }, care: ["No permitas punciones o mediciones de presión en el brazo de fístula sin consultar.|Observa el acceso y comunica cambios de vibración o sangrado.|Con catéter, no retires apósitos ni abras conexiones en casa.", "Pregunta por tu objetivo de diálisis y los análisis de seguimiento.|Informa calambres, mareo o falta de aire durante o entre sesiones.|Organiza atención si pierdes una sesión.", "Confirma qué fármacos se toman antes o después de diálisis.|Los quelantes de fósforo, si se prescriben, tienen horarios ligados a comidas.|Evita suplementos y antiinflamatorios sin revisión renal.", "La proteína y los líquidos pueden diferir del plan previo a diálisis.|Potasio, fósforo y sodio se ajustan a tus análisis.|No cambies líquidos basándote solo en sed o un consejo ajeno.", "Adapta actividad a cansancio y estabilidad de presión.|Protege el acceso de golpes y cargas no autorizadas.|Pide ejercicios adecuados para tu fuerza y equilibrio.", "Planifica apoyos para traslados y tiempos de tratamiento.|Comparte dificultades para mantener el calendario.|Solicita apoyo emocional si la diálisis afecta tus actividades o relaciones."], urgent: "Sangrado del acceso que no cede, falta de aire intensa, desmayo o confusión: ayuda inmediata.", contact: "Fiebre, dolor o secreción del acceso, o desaparición de la vibración de una fístula: contacta de inmediato al centro.", source: ["Diálisis", "dialysis.html"] },
  { parent: "gastroenterologia", slug: "colonoscopia", focus: "Preparación y cuidados de la colonoscopia", audience: "Personas con colonoscopia solicitada; el preparado depende del centro y de tus enfermedades.", overview: "Una cámara flexible permite observar el colon y, en ocasiones, retirar pólipos o tomar biopsias. Una limpieza adecuada es importante para que el estudio sea útil.", education: { signs: "Puede indicarse por sangrado, cambios intestinales o prevención. El motivo del estudio no equivale por sí mismo a un diagnóstico de cáncer.", evaluation: "Antes se revisan antecedentes, medicamentos y la seguridad de sedación. Pregunta qué ocurrirá si se encuentran pólipos.", preparation: "Obtén por escrito el laxante, horarios, alimentos y líquidos permitidos. No uses una preparación de otra persona; organiza baño accesible y acompañante.", followup: "Confirma cuándo volver a comer, conducir o tomar fármacos y quién entregará biopsias. Las restricciones cambian si se retiró un pólipo." }, care: ["Revisa las instrucciones con tiempo y avisa si no logras completar el preparado.|Observa mareo o signos de deshidratación durante la limpieza.|Tras sedación, vuelve acompañado y sigue el alta.", "Confirma indicación, alternativas y riesgos según tu caso.|Pregunta cómo recibir hallazgos y resultados de biopsia.|No ignores dolor intenso o sangrado importante después del estudio.", "Acuerda el plan de anticoagulantes y tratamiento de diabetes antes de iniciar el preparado.|No suspendas medicamentos por intuición.|No añadas otros laxantes al esquema prescrito.", "Sigue la dieta y el ayuno que indique el centro.|Los líquidos claros y sus colores permitidos deben confirmarse en la hoja de preparación.|Consulta si tienes restricciones de líquidos, riñón o corazón.", "No se necesita una rutina de ejercicio para preparar el colon.|Mantén acceso seguro al baño y levántate despacio si hay mareo.|Respeta restricciones posteriores si hubo sedación o intervención.", "Pide explicar el procedimiento y cómo se preservará tu privacidad.|Expresa preocupación por dolor, sedación o resultados.|Prepara preguntas y un acompañante si lo deseas."], urgent: "Dolor abdominal intenso o progresivo, desmayo, abdomen muy distendido o sangrado abundante después: urgencias.", contact: "No toleras el preparado, vomitas repetidamente o no puedes seguir las instrucciones: contacta al centro antes del estudio.", source: ["Colonoscopia", "colonoscopy.html"] },
  { parent: "reumatologia", slug: "osteoporosis", focus: "Osteoporosis y prevención de fracturas", audience: "Personas con osteoporosis o riesgo de fractura; no todas necesitan el mismo tratamiento.", overview: "La pérdida de resistencia del hueso aumenta el riesgo de fractura, incluso con golpes leves. La prevención combina evaluación del riesgo, ejercicio seguro y medicamentos cuando se indican.", education: { signs: "La osteoporosis suele ser silenciosa hasta una fractura. Dolor de espalda nuevo, pérdida de estatura o una fractura por golpe leve ameritan valoración.", evaluation: "La densitometría y los antecedentes ayudan a estimar riesgo; una cifra aislada no resume todos tus factores.", preparation: "Lleva fracturas previas, medicamentos y suplementos. Revisa riesgos de caída en casa y salud dental si se propone un tratamiento que lo requiera.", followup: "Pregunta cuándo repetir evaluación y cuánto tiempo usar el tratamiento. Algunos medicamentos no deben retrasarse o suspenderse sin un plan alternativo." }, care: ["Revisa iluminación, calzado y obstáculos para reducir caídas.|Aprende formas seguras de levantar objetos y cambiar de posición.|Comunica dolor de espalda tras un esfuerzo o caída.", "Acuerda tratamiento según riesgo de fractura y enfermedades asociadas.|Investiga causas secundarias cuando el equipo lo indique.|No suspendas un medicamento porque no sientes síntomas.", "Cada fármaco tiene técnica y calendario distintos: pide una demostración.|Confirma medidas de seguridad digestiva, renal o dental que correspondan.|No omitas inyecciones programadas sin consultar.", "Valora calcio y vitamina D con el equipo, evitando megadosis.|Incluye proteínas y alimentos ricos en calcio según tolerancia.|No reemplaces la comida por suplementos.", "Trabaja fuerza, equilibrio y actividad con carga adecuada a tu riesgo.|Con fracturas vertebrales, evita ejercicios de flexión o impacto no autorizados.|Una rutina supervisada reduce temor y mejora función.", "El miedo a fracturarte no debe llevar a inmovilidad total.|Acuerda metas pequeñas de movimiento seguro.|Solicita apoyo si una fractura limita independencia y ánimo."], urgent: "Caída con dolor intenso, deformidad o imposibilidad para apoyar; dolor de espalda con debilidad nueva: urgencias.", contact: "Pérdida de altura, dolor persistente o una dosis de tratamiento que no puedes recibir.", source: ["Osteoporosis", "osteoporosis.html"] },
  { parent: "hematologia", slug: "trombosis-venosa", focus: "Trombosis venosa profunda y anticoagulación", audience: "Personas con trombosis diagnosticada y anticoagulación prescrita.", overview: "Un coágulo en una vena profunda puede dificultar el retorno de sangre y, si se desplaza, afectar el pulmón. El tratamiento reduce complicaciones y requiere atención al riesgo de sangrado.", education: { signs: "Dolor e hinchazón de una pierna pueden ser señales, pero necesitan valoración. No toda hinchazón es trombosis ni debe masajearse.", evaluation: "El equipo valora riesgo y suele utilizar ecografía y, según el caso, análisis. La duración del tratamiento depende de la causa y evolución.", preparation: "Conoce nombre, dosis prescrita y horario de tu anticoagulante. Informa procedimientos próximos y usa una lista de medicamentos actualizada.", followup: "Consulta controles necesarios, restricciones y qué hacer ante olvido o sangrado. Algunos anticoagulantes requieren INR y otros no." }, care: ["Observa cambios de pierna y signos de sangrado.|Evita golpes y no masajees la zona afectada.|Pregunta cómo cuidar punciones y pequeñas heridas.", "Confirma causa probable y duración del tratamiento.|Avisa antes de cirugía, atención dental o embarazo.|No sustituyas la evaluación por medir la pierna en casa.", "No cambies dosis ni dupliques una toma olvidada sin seguir la pauta de tu medicamento.|Consulta antes de aspirina, antiinflamatorios o productos herbales.|Si usas warfarina, cumple el control de INR indicado.", "Con warfarina, mantén estable la ingesta de vitamina K en lugar de eliminar verduras.|Otros anticoagulantes tienen instrucciones alimentarias diferentes.|Consulta alcohol y suplementos según tu tratamiento.", "Pregunta cuándo caminar y retomar actividad; no impongas reposo prolongado por tu cuenta.|Usa medias solo si se indicaron y están bien ajustadas.|Evita deportes con alto riesgo de golpes durante anticoagulación.", "Prepara un plan para viajes y actividades con el equipo.|Habla del miedo a embolia o a sangrar.|Solicita apoyo para mantener el calendario sin ansiedad excesiva."], urgent: "Falta de aire súbita, dolor de pecho, tos con sangre, desmayo o sangrado importante: emergencia.", contact: "Nueva hinchazón o dolor de pierna, sangrado repetido o dosis omitidas: consulta al equipo.", source: ["Trombosis venosa profunda", "deepveinthrombosis.html"] },
  { parent: "oncologia", slug: "radioterapia", focus: "Cuidados durante radioterapia externa", audience: "Personas con radioterapia externa; braquiterapia y radiofármacos tienen precauciones diferentes.", overview: "La radiación dirigida trata una zona concreta. Los efectos dependen del sitio y del plan, por lo que no todas las personas tienen los mismos cambios de piel, digestión o energía.", education: { signs: "Puede haber cansancio o efectos locales en la zona tratada. Pregunta qué síntomas son previsibles en tu campo de radiación.", evaluation: "La planificación busca dirigir el tratamiento y proteger tejidos. Expresa dificultades para mantener postura o acudir a sesiones.", preparation: "Sigue las instrucciones de marcas, piel, ropa y, cuando corresponda, llenado de vejiga o dieta. No las adaptes por cuenta propia.", followup: "Algunos efectos continúan después de la última sesión. Confirma controles y a quién avisar si aparecen cambios tardíos." }, care: ["Lava y cuida la zona según el servicio; evita frotar o borrar marcas.|No uses calor, hielo o productos nuevos sobre el campo sin consultar.|Informa ampollas, secreción o dolor que aumenta.", "Pregunta el objetivo del tratamiento y efectos esperados por localización.|No faltes sin avisar: el centro puede ayudarte a reorganizar sesiones.|La radioterapia externa no te vuelve radiactivo.", "Revisa cremas, analgésicos y otros medicamentos con el equipo.|No apliques remedios naturales o perfumes en la zona tratada sin permiso.|Consulta antes de suplementos antioxidantes en dosis altas.", "La dieta depende del área irradiada y de síntomas como dolor al tragar o diarrea.|Informa pérdida de peso antes de que limite las sesiones.|No ayunes ni adoptes dietas anticáncer sin indicación.", "Mantén actividad suave adaptada al cansancio.|Solicita medidas de movilidad si la postura de tratamiento resulta dolorosa.|No fuerces piel irritada ni zonas con riesgo óseo.", "Organiza descanso y apoyo para traslados.|Comparte incertidumbre por resultados o efectos corporales.|La psicooncología puede acompañarte durante y después del tratamiento."], urgent: "Dificultad respiratoria, sangrado importante, confusión o incapacidad marcada para beber: atención urgente.", contact: "Reacción cutánea importante, dolor al tragar, diarrea persistente o pérdida de peso.", source: ["Radioterapia", "radiationtherapy.html"] },
  { parent: "infectologia", slug: "infeccion-urinaria", focus: "Infección de vías urinarias", audience: "Personas evaluadas por síntomas urinarios; embarazo, infancia o fiebre requieren atención específica.", overview: "La infección puede afectar vejiga o riñones. El tratamiento depende de síntomas, antecedentes y, cuando se solicita, cultivo; el olor de la orina por sí solo no confirma infección.", education: { signs: "Ardor, urgencia y dolor bajo pueden aparecer. Fiebre, dolor de costado o mal estado sugieren un problema que necesita valoración pronta.", evaluation: "Se revisan síntomas y factores de riesgo; el análisis o cultivo se interpreta junto a la clínica, no de forma aislada.", preparation: "Si se pide muestra, aprende su recolección antes del antibiótico cuando el equipo lo indique, sin retrasar atención urgente.", followup: "Confirma cuándo esperas mejorar y quién revisa el cultivo. No repitas antibióticos antiguos ante cada molestia." }, care: ["Registra fiebre, dolor y capacidad para beber.|Solicita instrucciones para higiene y muestra limpia.|Comunica si hay embarazo o catéter urinario.", "Pregunta si se necesita cultivo y cómo cambiará el manejo.|No toda bacteria en orina requiere tratamiento en ausencia de síntomas.|Consulta si empeoras o no mejoras en el plazo acordado.", "Toma el antibiótico exactamente como se prescribe.|No uses sobrantes ni lo compartas.|Informa alergias, enfermedad renal e interacciones.", "Mantén líquidos dentro de tus restricciones y tolerancia.|No fuerces grandes volúmenes con enfermedad renal o cardíaca.|Los suplementos no sustituyen un antibiótico indicado.", "La fisioterapia no trata la infección aguda.|Descansa si hay fiebre y retoma actividad según mejoría.|Si hay problemas persistentes de vaciado, el equipo puede valorar otras intervenciones.", "Expresa molestias sin vergüenza y pide privacidad.|No atribuyas síntomas a culpa o falta de higiene.|Ante recurrencias, solicita un plan en vez de automedicarte."], urgent: "Fiebre con dolor de costado, vómitos, confusión o deterioro rápido: busca valoración urgente.", contact: "Síntomas persistentes, embarazo o nueva dificultad para orinar.", source: ["Infecciones de las vías urinarias", "urinarytractinfections.html"] },
  { parent: "geriatria", slug: "demencia", focus: "Demencia: autonomía y apoyo al cuidador", audience: "Personas con demencia y sus redes de cuidado; la confusión súbita no se considera evolución normal.", overview: "La demencia afecta memoria y otras capacidades de forma persistente. El cuidado busca seguridad, participación y calidad de vida según la etapa y preferencias de cada persona.", education: { signs: "Olvidos que afectan tareas, desorientación o cambios de lenguaje merecen evaluación. Un cambio brusco en horas o días necesita buscar otra causa.", evaluation: "Se revisan memoria, función, medicamentos y posibles causas tratables. La valoración no se limita a una prueba breve.", preparation: "Organiza rutinas y apoyos sin retirar decisiones innecesariamente. Revisa seguridad en cocina, salidas, baño y manejo de dinero con la familia.", followup: "Planifica descanso del cuidador y contactos de apoyo. Revisa deglución, caídas, sueño y conductas que cambian." }, care: ["Usa instrucciones breves, una tarea a la vez y objetos familiares.|Adapta higiene y vestido conservando capacidades.|Observa dolor, estreñimiento o infección si cambia la conducta.", "Pide explicar diagnóstico, etapa y cambios que requieren reevaluación.|La confusión repentina no debe atribuirse automáticamente a demencia.|Incluye decisiones anticipadas respetando capacidad y preferencias.", "Revisa fármacos que causan sueño o confusión.|Usa un sistema supervisado si hay errores de toma.|No uses sedantes o antipsicóticos para conveniencia sin valoración.", "Ofrece un entorno tranquilo y vigila peso e hidratación.|Consulta si hay tos al comer o dificultad para tragar.|No cambies texturas ni suplementos sin evaluar necesidades.", "Mantén paseos y tareas adaptadas a equilibrio y orientación.|Supervisa sin restringir toda movilidad.|Solicita evaluación de ayudas técnicas y prevención de caídas.", "Valida emociones y evita discutir para imponer recuerdos correctos.|Organiza descansos y apoyo al cuidador.|Busca ayuda ante agotamiento, tristeza o conductas que ponen en riesgo."], urgent: "Confusión súbita, debilidad de un lado, somnolencia intensa o incapacidad para despertar: urgencias.", contact: "Pérdida de peso, atragantamientos, nuevas caídas o agotamiento del cuidador.", source: ["Demencia", "dementia.html"] },
  { parent: "pediatria", slug: "bronquiolitis", focus: "Bronquiolitis en bebés", audience: "Cuidadores de lactantes con bronquiolitis evaluada; prematuros y bebés pequeños pueden tener mayor riesgo.", overview: "La inflamación viral de las vías respiratorias pequeñas dificulta respirar y alimentarse. El cuidado se centra en respiración e hidratación; no es lo mismo que el asma.", education: { signs: "Vigila hundimiento entre costillas, pausas respiratorias, color y capacidad para alimentarse. La frecuencia de tomas y pañales ayuda a detectar deterioro.", evaluation: "La valoración incluye esfuerzo respiratorio, hidratación y, si corresponde, oxígeno. No todos necesitan radiografía o antibiótico.", preparation: "Aprende limpieza nasal suave si está indicada y mantén ambiente sin humo. Para dormir, conserva una superficie firme y posición boca arriba.", followup: "Confirma cuándo volver a revisión y no esperes si empeora. No uses almohadas ni inclines la cuna para tratar la congestión." }, care: ["Observa respiración, tomas y pañales mojados.|Pide demostrar higiene nasal suave antes de alimentar si se indicó.|No hagas aspiraciones profundas por tu cuenta.", "Consulta antes si el bebé es pequeño, prematuro o tiene enfermedad de base.|El ingreso depende de respiración, oxígeno e hidratación.|Busca ayuda si el bebé no puede alimentarse por falta de aire.", "No uses jarabes para tos, antibióticos o broncodilatadores de otro niño.|Los medicamentos para fiebre deben indicarse según edad y peso.|La bronquiolitis viral no se cura con antibiótico de rutina.", "Ofrece tomas pequeñas y frecuentes si el bebé respira y traga con seguridad.|Mantén lactancia si se tolera.|No fuerces la alimentación cuando hay dificultad respiratoria importante.", "No realices percusión o fisioterapia torácica de rutina.|Evita forzar posturas o ejercicios respiratorios.|Pide recomendaciones de descanso y manipulación cómoda.", "Reparte la vigilancia entre cuidadores para poder descansar.|Usa una lista simple de señales de alarma compartida.|Si te preocupa un cambio del bebé, consulta sin esperar a completar registros."], urgent: "Pausas al respirar, color azulado, agotamiento, respuesta anormal o gran dificultad respiratoria: emergencias.", contact: "Menos tomas, menos pañales mojados, fiebre o más esfuerzo para respirar.", source: ["Bronquiolitis", "ency/article/000975.htm"] },
  { parent: "cirugia-general", slug: "colecistectomia", focus: "Colecistectomía: cirugía de vesícula", audience: "Personas con extirpación de vesícula indicada o reciente.", overview: "La cirugía retira la vesícula, a menudo por cálculos que causan problemas. Puede hacerse por pequeñas incisiones o por cirugía abierta y no implica retirar el hígado.", education: { signs: "Dolor abdominal, fiebre o ictericia necesitan valoración; no todas las molestias digestivas se deben a la vesícula.", evaluation: "El equipo revisa imágenes, análisis y riesgo anestésico. Pregunta si la cirugía será abierta o laparoscópica y si se prevé drenaje.", preparation: "Confirma ayuno, acompañante y ajustes de medicamentos. Organiza ayuda en casa y una copia de las indicaciones de alta.", followup: "Revisa herida, tolerancia a comidas y tránsito intestinal. Solicita valoración si el dolor empeora o aparecen ojos amarillos." }, care: ["Aprende cuándo retirar o cambiar apósitos según tu cierre de piel.|No manipules drenajes ni pegamento quirúrgico.|Registra dolor, temperatura y tolerancia a alimentos.", "Confirma límites de carga, conducción y regreso al trabajo.|Pregunta qué molestias pueden aparecer tras laparoscopia.|Acude a revisión aunque las incisiones sean pequeñas.", "Toma analgesia según receta sin combinar ingredientes repetidos.|Revisa qué medicamentos se reinician y cuándo.|No uses antibióticos sobrantes para prevenir infección.", "Reanuda comidas según tolerancia y el alta.|Porciones pequeñas pueden ser más cómodas si las comidas grasas generan molestias.|No mantengas una dieta muy restrictiva sin valoración.", "Camina de forma progresiva y descansa entre actividades.|Evita cargas abdominales hasta autorización.|Solicita técnica para levantarte sin esfuerzo excesivo.", "Prepara apoyo para traslados y primeras tareas en casa.|Pregunta por cambios esperables para reducir incertidumbre.|Pide ayuda si el temor al dolor impide movilizarte."], urgent: "Dolor abdominal intenso o progresivo, ictericia con fiebre, dificultad respiratoria o desmayo: urgencias.", contact: "Fiebre, herida con secreción, vómitos persistentes o diarrea que no mejora.", source: ["Enfermedades de la vesícula biliar", "gallbladderdiseases.html"] },
  { parent: "traumatologia-ortopedia", slug: "artroplastia-rodilla", focus: "Reemplazo de rodilla", audience: "Personas con artroplastia de rodilla y sus cuidadores.", overview: "La artroplastia sustituye superficies dañadas de la articulación. La recuperación requiere control del dolor, prevención de complicaciones y rehabilitación individual.", education: { signs: "Antes de operar se valora cómo el dolor limita la función. Después se vigilan herida, hinchazón y capacidad para caminar.", evaluation: "La indicación depende de síntomas, imágenes y tratamientos previos. No todas las rodillas dolorosas necesitan prótesis.", preparation: "Practica con el equipo el uso de ayuda de marcha y prepara trayectos seguros en casa. Confirma apoyo de peso y medicación.", followup: "Mantén revisiones y ejercicios prescritos. La flexión, fuerza y tiempos de regreso varían; no fuerces metas de otra persona." }, care: ["Observa incisión y cambios de hinchazón o dolor.|Sigue el plan de elevación o frío si se indicó y protege la piel.|Pide ayuda para baño y transferencias seguras.", "Confirma cuánto peso puedes apoyar y cuándo revisar la herida.|Pregunta qué síntomas sugieren infección o coágulo.|No retires puntos o grapas por tu cuenta.", "Comprende duración de prevención de coágulos si se prescribió.|Coordina analgesia con el programa de rehabilitación según receta.|Comunica somnolencia, sangrado o estreñimiento.", "Mantén energía y proteínas suficientes para cicatrización.|Consulta medidas para estreñimiento asociado a analgesia.|Evita suplementos innecesarios para acelerar una prótesis.", "Realiza ejercicios de movilidad y fuerza enseñados para tu etapa.|Practica marcha y escaleras con supervisión inicial.|No uses dolor intenso como señal de que debes forzar más.", "Fija objetivos funcionales semanales con el equipo.|Habla del miedo a caer o de la frustración por avances lentos.|Organiza apoyo sin perder participación en tus cuidados."], urgent: "Falta de aire súbita, dolor de pecho, pie frío o pérdida brusca de fuerza: emergencia.", contact: "Pantorrilla nueva dolorosa o hinchada, fiebre o secreción de herida: valoración pronta.", source: ["Alta tras artroplastia de rodilla", "ency/patientinstructions/000170.htm"] },
  { parent: "neurocirugia", slug: "craneotomia", focus: "Cuidados después de craneotomía", audience: "Personas dadas de alta tras cirugía cerebral y cuidadores; el motivo de cirugía determina precauciones adicionales.", overview: "La craneotomía permite acceder al cerebro a través del cráneo. La recuperación puede afectar energía, memoria, movimiento o lenguaje, según la zona y la enfermedad tratada.", education: { signs: "Compara alerta, fuerza, habla y visión con el estado al alta. Cambios nuevos o progresivos requieren atención.", evaluation: "Confirma qué operación se realizó y qué resultados o estudios siguen pendientes. No todas las cirugías cerebrales tienen la misma evolución.", preparation: "Organiza supervisión inicial, descanso y medicación clara. Pregunta por cuidado del cuero cabelludo y fecha de revisión.", followup: "La vuelta a conducción, trabajo y actividad se autoriza individualmente. Si falta parte del hueso, pide instrucciones de protección específicas." }, care: ["Cuida la incisión según el alta y evita productos capilares no autorizados.|Registra cambios de conducta o somnolencia.|No presiones ni manipules una zona desprotegida del cráneo.", "Confirma cuándo revisar puntos, imágenes y resultados.|Informa cualquier cambio neurológico nuevo.|Pregunta por restricciones de conducción y actividades de riesgo.", "Si se indicaron antiepilépticos o corticoides, sigue el calendario exacto.|No retires tratamientos de golpe.|Pide un esquema que evite confusión entre dosis y horarios.", "Mantén ingesta suficiente y comunica náusea o dificultad para tragar.|La textura se adapta si existe alteración de deglución.|No inicies suplementos para el cerebro sin consultar.", "Trabaja movilidad y equilibrio según déficits y autorización.|La recuperación puede requerir terapia ocupacional o de lenguaje.|Evita actividades con riesgo de golpe de cabeza.", "Explica cambios emocionales y de memoria sin culpabilizar a la persona.|Usa rutinas sencillas y descansos.|Solicita apoyo para cuidadores y adaptación a nuevas capacidades."], urgent: "Debilidad nueva, convulsión, dificultad para hablar, dolor de cabeza intenso con vómitos o dificultad para despertar: urgencias.", contact: "Fiebre, herida que se abre o drena, o cambios progresivos de memoria y conducta.", source: ["Alta tras cirugía del cerebro", "ency/patientinstructions/000124.htm"] },
  { parent: "cirugia-cardiaca", slug: "cirugia-valvular", focus: "Reparación o reemplazo de válvula cardíaca", audience: "Personas con intervención valvular; válvula mecánica, biológica y reparación tienen planes diferentes.", overview: "Las válvulas dirigen la sangre dentro del corazón. Si se estrechan o no cierran bien, pueden requerir reparación o reemplazo por cirugía o por catéter.", education: { signs: "Antes o después se valoran falta de aire, edema, palpitaciones y tolerancia al esfuerzo. No todos los síntomas se explican por la válvula.", evaluation: "El ecocardiograma y otras pruebas ayudan a elegir la intervención. Conoce el tipo de válvula o reparación que recibiste.", preparation: "Guarda tu informe y tarjeta del implante si se proporciona. Confirma medicamentos, revisiones y medidas de cuidado dental.", followup: "El tratamiento antitrombótico y su duración dependen de la válvula. Pregunta cuándo necesitas prevención de infección para procedimientos concretos." }, care: ["Observa incisión o zona de punción y cambios de respiración.|Registra síntomas según tu hoja de alta.|Mantén higiene de boca y consulta lesiones o infecciones.", "Confirma tipo de válvula y controles ecocardiográficos.|Pregunta qué procedimientos requieren medidas especiales.|Una fiebre sin causa merece consulta si tienes una prótesis.", "No cambies anticoagulante ni lo sustituyas por otro sin cardiología.|Si usas warfarina, cumple el objetivo y controles de INR indicados.|Informa cualquier sangrado o procedimiento planeado.", "Sigue alimentación cardioprotectora con líquidos individualizados.|Con warfarina, evita cambios bruscos de vitamina K, no todas las verduras.|Revisa alcohol y suplementos con el equipo.", "Pregunta por rehabilitación cardíaca y límites de esfuerzo.|Si hubo apertura esternal, sigue precauciones específicas.|Retoma caminatas de manera progresiva, no pruebas de esfuerzo caseras.", "Conoce tu implante para reducir incertidumbre.|Practica organizar controles y medicamentos con apoyo.|Habla del miedo a sangrado o nuevas intervenciones."], urgent: "Dolor de pecho, falta de aire súbita, desmayo o signos de ictus: emergencias.", contact: "Fiebre, palpitaciones persistentes, edema creciente o sangrado durante anticoagulación.", source: ["Enfermedades de las válvulas del corazón", "heartvalvediseases.html"] },
  { parent: "angiologia-cirugia-vascular", slug: "varices", focus: "Várices y procedimientos venosos", audience: "Personas con várices evaluadas o tras ablación, escleroterapia o cirugía venosa.", overview: "Las venas dilatadas pueden causar pesadez, hinchazón o cambios de piel. El tratamiento depende del estudio de circulación; una várice no es lo mismo que una obstrucción arterial.", education: { signs: "Observa dolor, hinchazón y lesiones de piel. Una pierna súbitamente hinchada o muy dolorosa necesita descartar otra causa.", evaluation: "La exploración y, cuando procede, ecografía venosa orientan si se necesitan medias o intervención.", preparation: "Pregunta qué técnica recibirás, si requiere ayuno y cómo usar medias si se prescriben. Informa enfermedad arterial y tratamientos anticoagulantes.", followup: "Confirma calendario de caminatas, compresión y revisión. No asumas que todas las técnicas tienen idénticas restricciones." }, care: ["Cuida puntos de punción y piel según la técnica realizada.|No manipules ampollas o zonas lesionadas.|Solicita enseñanza del ajuste de medias cuando se indiquen.", "Aclara si se requiere procedimiento o manejo conservador.|Pregunta qué molestias son esperables y cuándo controlar la circulación.|No trates en casa una vena que está sangrando de forma importante.", "Revisa analgesia y tratamientos previos al procedimiento.|No tomes productos para circulación sin revisar riesgos.|No suspendas anticoagulantes sin plan acordado.", "Mantén alimentación suficiente y peso saludable sin dietas rápidas.|Si hay úlcera, pide evaluación de ingesta y cicatrización.|Los suplementos no corrigen por sí solos insuficiencia venosa.", "Evita permanecer inmóvil muchas horas y camina según indicación.|La compresión requiere valoración y talla correctas.|No uses medias si existe sospecha de mala circulación arterial sin evaluación.", "Comparte si las molestias limitan trabajo o sueño.|Define objetivos de confort y función además de apariencia.|Pregunta por expectativas realistas y posibilidad de recurrencia."], urgent: "Sangrado venoso que no cede, falta de aire súbita o dolor torácico: emergencia.", contact: "Nueva hinchazón marcada de una pierna, dolor creciente, fiebre o úlcera.", source: ["Várices", "varicoseveins.html"] },
  { parent: "cirugia-toracica", slug: "toracocentesis", focus: "Toracocentesis: extracción de líquido pleural", audience: "Personas con punción pleural indicada o reciente.", overview: "La toracocentesis extrae líquido del espacio que rodea al pulmón para estudiarlo o aliviar síntomas. La cantidad y la técnica las determina el personal capacitado.", education: { signs: "Un derrame pleural puede causar falta de aire o dolor; tiene diversas causas y requiere investigación.", evaluation: "Se revisan imágenes, ubicación del líquido y riesgo de sangrado. La muestra puede analizarse para distintas causas.", preparation: "Informa anticoagulantes y alergias y confirma si necesitas ayuno. Sigue la postura y las instrucciones de inmovilidad durante la punción.", followup: "Pregunta si se necesita observación o imagen posterior, cuidado del apósito y fecha del resultado del líquido." }, care: ["Comunica dolor, tos o falta de aire durante el procedimiento.|Mantén la postura indicada y pide ayuda si no puedes sostenerla.|Revisa el punto de punción y el apósito al volver a casa.", "Pregunta qué causa de derrame se está investigando.|Conoce riesgos y qué cambios respiratorios requieren regresar.|El alivio de síntomas no elimina la necesidad de estudiar la causa.", "Los ajustes de anticoagulantes se acuerdan antes del procedimiento.|No los suspendas ni reinicies por tu cuenta.|Confirma analgesia permitida si hay molestia local.", "No se necesita una dieta especial por la punción de rutina.|Confirma ayuno si se usará sedación.|Los líquidos dependen de la enfermedad causante, no solo del derrame.", "No hagas ejercicios intensos para forzar expansión tras la punción.|Respira con naturalidad y sigue las indicaciones de actividad.|La rehabilitación respiratoria se añade solo si se valora necesaria.", "Pide conocer las sensaciones esperables y cómo avisar molestias.|Usa un acompañante si ayuda a tu tranquilidad.|Pregunta cuándo recibirás resultados para organizar la espera."], urgent: "Falta de aire nueva o creciente, dolor torácico intenso, desmayo o tos con sangre después: urgencias.", contact: "Fiebre, sangrado o secreción en punción, o dudas sobre resultados.", source: ["Toracocentesis", "ency/article/003420.htm"] },
  { parent: "cirugia-plastica-reconstructiva", slug: "quemaduras", focus: "Quemaduras: cuidados y recuperación", audience: "Personas con quemaduras ya valoradas y sus cuidadores; las lesiones extensas necesitan atención especializada.", overview: "El cuidado depende de profundidad, extensión, ubicación y causa. No todas las quemaduras se tratan en casa ni precisan el mismo apósito o rehabilitación.", education: { signs: "Dolor, ampollas o pérdida de sensibilidad no permiten estimar toda la gravedad. Lesiones químicas, eléctricas o por inhalación requieren evaluación especial.", evaluation: "El equipo valora profundidad, extensión, zonas afectadas y riesgo respiratorio. Pregunta si se precisa unidad de quemados.", preparation: "Recibe una demostración del apósito y materiales autorizados. No revientes ampollas ni apliques pasta dental, aceites o hielo directo.", followup: "Las indicaciones de movilidad, protección solar y cicatriz cambian a medida que cierra la piel. Consulta antes de masajes o prendas compresivas." }, care: ["Aprende la técnica y frecuencia exactas del cambio de apósito.|No retires piel ni ampollas por tu cuenta.|Observa infección, dolor creciente y cambio de color.", "Confirma profundidad y plan de revisiones y vacunas según el caso.|Lesiones en cara, manos o articulaciones pueden necesitar cuidados especializados.|No minimices una quemadura poco dolorosa pero profunda.", "Usa solo los tópicos y analgésicos indicados.|Consulta alergias y duración de tratamientos.|No uses antibióticos sistémicos por prevención sin receta.", "Las quemaduras extensas pueden aumentar necesidades de energía y proteína.|Informa pérdida de peso o ingesta insuficiente.|Evita dietas restrictivas durante cicatrización.", "Mantén movilidad de articulaciones según el plan de protección de la herida.|Los estiramientos y férulas requieren enseñanza individual.|No fuerces tejido recién injertado.", "El dolor, la hospitalización y los cambios corporales pueden afectar el ánimo.|Pide estrategias para procedimientos y adaptación a cicatrices.|Incluye apoyo familiar y regreso gradual a actividades."], urgent: "Dificultad para respirar tras humo, quemadura extensa, eléctrica, química o deterioro rápido: atención inmediata.", contact: "Fiebre, mal olor, secreción, dolor creciente o limitación de una articulación.", source: ["Quemaduras", "burns.html"] },
  { parent: "coloproctologia", slug: "hemorroides", focus: "Hemorroides y cuidados tras su tratamiento", audience: "Personas con hemorroides confirmadas o después de ligadura o cirugía.", overview: "Las hemorroides son vasos aumentados alrededor del ano o recto. Pueden sangrar o doler, pero el sangrado rectal no debe atribuirse automáticamente a ellas.", education: { signs: "Sangrado, picor, dolor o bulto pueden aparecer. La evaluación ayuda a distinguir fisuras y otras causas.", evaluation: "El tratamiento depende de síntomas y tipo; puede incluir hábitos, procedimientos ambulatorios o cirugía.", preparation: "Consulta cómo mantener heces cómodas y qué cuidados corresponden a la técnica. No apliques un enema sin confirmar si está permitido.", followup: "Confirma qué sangrado es esperable y cuándo revisar. Acude si hay fiebre, dolor intenso o dificultad para orinar tras el procedimiento." }, care: ["Realiza higiene suave sin frotar ni usar productos irritantes.|Sigue indicaciones de baño local y apósito si corresponden.|Observa cantidad y evolución del sangrado.", "Solicita evaluación del sangrado, especialmente si es nuevo o persistente.|Pregunta qué procedimiento se realizó y sus restricciones.|No retires por tu cuenta material de una ligadura.", "Usa cremas y analgésicos por el tiempo prescrito.|Consulta antes de laxantes o antiinflamatorios si hay sangrado.|No prolongues corticoides tópicos sin revisión.", "La fibra se ajusta gradualmente y con líquidos autorizados.|Evita pujar y consulta si el estreñimiento persiste.|No reduzcas tanto la comida que dificulte la recuperación.", "Evita permanecer sentado mucho tiempo en el inodoro.|Retoma caminatas y limita cargas según la técnica.|El suelo pélvico se evalúa si hay dificultad funcional, no se ejercita indiscriminadamente.", "Habla de dolor o temor a evacuar sin vergüenza.|Acuerda una estrategia para que el miedo no lleve a retener heces.|Solicita privacidad y explicación de cada exploración."], urgent: "Sangrado abundante, desmayo, fiebre con dolor anal intenso o incapacidad para orinar tras procedimiento: urgencias.", contact: "Sangrado persistente, empeoramiento del dolor o estreñimiento pese al plan.", source: ["Hemorroides", "hemorrhoids.html"] },
  { parent: "ginecologia", slug: "endometriosis", focus: "Endometriosis y dolor pélvico", audience: "Personas con sospecha o diagnóstico de endometriosis.", overview: "El tejido similar al revestimiento uterino fuera del útero puede causar dolor y otros problemas. La intensidad del dolor y la extensión de lesiones no siempre coinciden.", education: { signs: "Dolor menstrual intenso, dolor al tener relaciones o molestias intestinales cíclicas merecen evaluación. No es necesario normalizar dolor incapacitante.", evaluation: "La historia, exploración e imágenes ayudan a orientar el diagnóstico. La necesidad de cirugía se decide de forma individual.", preparation: "Registra ciclo, dolor, sangrado y limitación funcional. Expresa deseos reproductivos antes de elegir tratamiento.", followup: "Revisa eficacia y efectos del plan hormonal o analgésico. Si hubo cirugía, las indicaciones dependen de órganos y técnica tratados." }, care: ["Anota síntomas y actividades limitadas para la consulta.|Consulta cómo manejar dolor y sangrado en días difíciles.|Pide privacidad y consentimiento antes de exploraciones.", "Compara opciones médicas y quirúrgicas con sus objetivos.|Aclara cómo se relacionan con fertilidad y anticoncepción.|Un dolor nuevo intenso requiere valorar otras causas.", "Revisa pauta y efectos de tratamientos hormonales o analgésicos.|No combines antiinflamatorios sin consultar.|Informa migraña, trombosis u otras condiciones antes de hormonas.", "No hay una dieta única que cure endometriosis.|Si hay síntomas digestivos, solicita ajustes sin exclusiones extensas.|Vigila hierro si el sangrado es abundante y el equipo lo indica.", "Solicita valoración de suelo pélvico si hay dolor o tensión muscular.|No todos necesitan ejercicios de contracción: pueden empeorar tensión en algunos casos.|Adapta movimiento y descansos según tolerancia.", "El dolor persistente puede afectar ánimo e intimidad.|Pide herramientas de afrontamiento sin que se reduzca el dolor a una causa emocional.|Comparte decisiones y límites con tu pareja si lo deseas."], urgent: "Dolor pélvico súbito intenso, desmayo o sangrado abundante; dolor con posible embarazo: urgencias.", contact: "Dolor que interfiere con vida diaria, efectos de tratamiento o dificultades reproductivas.", source: ["Endometriosis", "endometriosis.html"] },
  { parent: "obstetricia", slug: "diabetes-gestacional", focus: "Diabetes gestacional", audience: "Personas embarazadas con diabetes gestacional y su red de apoyo.", overview: "La glucosa elevada detectada durante el embarazo requiere un plan materno-fetal. Alimentación, mediciones, actividad y, si se necesita, medicamentos se adaptan a esta etapa.", education: { signs: "Puede no producir síntomas. Los estudios prenatales permiten detectarla; no depende solo de haber comido dulces.", evaluation: "El equipo confirma el diagnóstico y acuerda metas de glucosa y vigilancia del embarazo. No uses metas de una persona no embarazada.", preparation: "Aprende a medir y registrar glucosa según horarios prescritos. Lleva comidas, síntomas y dudas a la consulta.", followup: "El plan cambia tras el parto y se necesita control posterior para detectar diabetes persistente. Confirma por escrito cuándo hacer la prueba posparto." }, care: ["Practica glucómetro, registro e higiene del sitio de punción.|Aprende señales y manejo individual de hipoglucemia si tu tratamiento la puede causar.|Comunica dificultad para obtener insumos.", "Mantén controles prenatales y seguimiento fetal que se indique.|Consulta qué hacer si vomitas o no puedes comer.|No retrases avisar valores repetidamente fuera de tus metas.", "Si se prescribe insulina u otro fármaco, confirma dosis y técnica individual.|No ajustes por un consejo general.|Revisa con farmacia medicamentos y suplementos del embarazo.", "Distribuye carbohidratos y comidas según tu plan de embarazo.|Evita ayunos y dietas para perder peso sin indicación.|No elimines todos los carbohidratos ni sustituyas comida por productos sin azúcar.", "Realiza actividad autorizada para tu embarazo.|No inicies ejercicio si existe contraindicación obstétrica.|Detén actividad si aparece sangrado, mareo o dolor preocupante.", "Evita culparte: las hormonas del embarazo influyen en la glucosa.|Pide apoyo práctico para comidas y mediciones.|Habla del temor por la salud del bebé con el equipo."], urgent: "Desmayo, confusión, dificultad respiratoria, sangrado o disminución de movimientos fetales: busca atención inmediata según tu plan obstétrico.", contact: "Glucosa fuera de metas, vómitos o dudas para administrar el tratamiento.", source: ["Diabetes y el embarazo", "diabetesandpregnancy.html"] },
  { parent: "urologia", slug: "reseccion-prostata", focus: "Resección transuretral de próstata (RTUP)", audience: "Personas operadas por crecimiento benigno de próstata; no es la misma cirugía que prostatectomía radical.", overview: "Se retira tejido prostático a través de la uretra para mejorar el paso de orina. Puede necesitarse una sonda temporal y vigilancia de sangrado.", education: { signs: "Antes se valoran chorro débil, retención y otras causas. Después importa distinguir molestias esperables de bloqueo de la sonda.", evaluation: "Confirma la técnica y si se analizará el tejido. Pregunta por cambios esperables en eyaculación y recuperación del control urinario.", preparation: "Aprende manejo de bolsa, higiene y prevención de tirones si vas a casa con sonda. Obtén fecha de retiro.", followup: "Revisa límites de carga, actividad sexual y conducción. El sangrado intenso o la imposibilidad de orinar requieren valoración." }, care: ["Mantén el sistema de sonda según enseñanza y evita desconexiones innecesarias.|La bolsa se coloca sin impedir drenaje ni provocar tirones.|No laves o retires la sonda por iniciativa propia.", "Confirma controles, resultado del tejido y retiro de sonda.|Pregunta qué urgencia, ardor o sangre pueden aparecer.|No ignores bloqueo de drenaje o dolor suprapúbico intenso.", "Confirma cuándo reiniciar anticoagulantes si se habían ajustado.|No añadas fármacos para próstata o vejiga sin revisión.|Consulta analgesia y estreñimiento.", "Acuerda líquidos con el equipo; no fuerces agua si tienes restricción.|Evita estreñimiento mediante el plan autorizado.|Informa náusea o imposibilidad para beber.", "Camina suavemente y respeta límites de carga.|El entrenamiento de suelo pélvico se adapta tras retirar sonda y valorar función.|No hagas esfuerzos que aumenten sangrado.", "Expresa dudas sobre continencia, erección o eyaculación.|Distingue cambios esperables de problemas que necesitan seguimiento.|Solicita apoyo si la sonda limita confianza o descanso."], urgent: "No drena orina con dolor, coágulos abundantes, sangrado intenso, fiebre con mal estado o desmayo: urgencias.", contact: "Molestias persistentes, fuga o problemas del dispositivo, o dudas sobre retiro de sonda.", source: ["Alta tras resección transuretral de la próstata", "ency/patientinstructions/000300.htm"] },
  { parent: "otorrinolaringologia", slug: "vertigo", focus: "Vértigo y rehabilitación vestibular", audience: "Personas con vértigo evaluado; un episodio nuevo con signos neurológicos necesita urgencias.", overview: "El vértigo es sensación de giro y puede tener causas del oído interno u otras. Su tratamiento depende del diagnóstico; no todas las maniobras sirven para todos los mareos.", education: { signs: "Anota duración, desencadenantes, audición y síntomas asociados. Un desequilibrio no siempre es vértigo posicional.", evaluation: "La exploración de ojos, oído y sistema nervioso orienta la causa. Algunas personas necesitan pruebas adicionales.", preparation: "Reduce riesgo de caídas y evita conducir si el giro está activo. Describe movimientos que desencadenan el episodio sin forzarlos solo para probarlo.", followup: "Si se indica maniobra de reposicionamiento o rehabilitación, aprende la técnica con personal capacitado. Consulta si cambia el patrón." }, care: ["Si comienza giro, siéntate en un lugar seguro y solicita apoyo.|Evita levantarte bruscamente o caminar a oscuras.|Observa vómitos y capacidad para beber.", "Confirma la causa probable y señales para reevaluar.|La pérdida súbita de audición necesita atención pronta.|Síntomas neurológicos nuevos no deben atribuirse al oído sin valoración.", "Los fármacos para mareo pueden causar somnolencia y no siempre deben prolongarse.|No conduzcas bajo sus efectos.|Revisa medicamentos que contribuyan a inestabilidad.", "Mantén líquidos dentro de tus restricciones si hubo vómitos.|No impongas dietas bajas en sal para cualquier vértigo: depende del diagnóstico.|Consulta si no toleras alimentos.", "La rehabilitación vestibular se adapta al diagnóstico y tolerancia.|No copies maniobras si hay enfermedad de cuello o no se confirmó vértigo posicional.|Trabaja equilibrio con un entorno protegido.", "El miedo a moverte puede aumentar limitación: recupera actividad con apoyo.|No se deben desestimar síntomas por ansiedad.|Pide estrategias para salir de casa con seguridad."], urgent: "Vértigo con debilidad, dificultad para hablar, visión doble nueva, desmayo o dolor de cabeza súbito intenso: emergencias.", contact: "Pérdida súbita de audición, vómitos persistentes o episodios que cambian de patrón.", source: ["Mareo y vértigo", "dizzinessandvertigo.html"] },
  { parent: "oftalmologia", slug: "glaucoma", focus: "Glaucoma y uso seguro de colirios", audience: "Personas con glaucoma diagnosticado o seguimiento por riesgo.", overview: "El glaucoma daña el nervio óptico y puede reducir visión de forma irreversible. A menudo no da síntomas al principio, por lo que controles y tratamiento son importantes aun cuando ves bien.", education: { signs: "La pérdida periférica puede pasar inadvertida. Dolor ocular intenso con visión borrosa y náusea puede ser una urgencia diferente al glaucoma crónico estable.", evaluation: "Presión ocular, nervio óptico y campo visual ayudan a vigilar daño. La presión por sí sola no resume toda la enfermedad.", preparation: "Lleva tus gotas y demuestra cómo las aplicas. Informa asma, problemas cardíacos y otros tratamientos porque algunos colirios tienen efectos generales.", followup: "Mantén fechas de controles y reposición de frascos. No suspendas gotas porque no notas cambios o no hay dolor." }, care: ["Aplica gotas con manos limpias sin tocar ojo ni pestañas con el frasco.|Comprueba ojo correcto y horario.|Solicita apoyo si temblor o visión dificultan la técnica.", "Conoce el objetivo y el calendario de pruebas.|Pregunta si láser o cirugía serían opciones para tu situación.|No esperes a notar pérdida de visión para acudir a control.", "Confirma cómo separar colirios y evitar contaminación.|Informa fatiga, mareo o problemas respiratorios tras iniciar gotas.|No sustituyas frascos por productos para ojo rojo.", "Una alimentación saludable no reemplaza el tratamiento.|No uses suplementos que prometan recuperar nervio óptico.|Consulta restricciones solo si existe otra enfermedad.", "No se requieren ejercicios oculares para curar glaucoma.|Adapta iluminación y equilibrio si disminuyó tu campo visual.|Si hubo cirugía, sigue restricciones propias de esa intervención.", "Organiza recordatorios discretos y apoyo para tomas.|Comparte temor por visión y pérdida de autonomía.|Solicita recursos de rehabilitación visual si se necesitan."], urgent: "Dolor ocular intenso, visión borrosa súbita, halos con náusea o pérdida repentina de visión: atención urgente.", contact: "Dificultad para usar gotas, efectos adversos o falta de acceso al tratamiento.", source: ["Glaucoma", "glaucoma.html"] },
  { parent: "dermatologia", slug: "acne", focus: "Acné: rutina y tratamiento", audience: "Adolescentes y adultos con acné; el tratamiento cambia según gravedad y posibilidad de embarazo.", overview: "El acné afecta folículos de la piel y puede dejar cicatrices. No se debe a suciedad ni se resuelve exprimiendo lesiones; los tratamientos suelen requerir tiempo y constancia.", education: { signs: "Comedones, lesiones inflamadas y nódulos necesitan enfoques diferentes. Consulta antes si hay cicatrices o dolor importante.", evaluation: "Se revisan gravedad, productos, medicamentos y factores hormonales cuando procede. No todas las lesiones de cara son acné.", preparation: "Lleva la lista de productos usados y evita añadir varios activos a la vez. Informa embarazo o intención de embarazo antes de tratamientos.", followup: "Confirma el plazo esperado para valorar respuesta y cómo manejar irritación. No aumentes frecuencia para acelerar resultados." }, care: ["Limpia con suavidad y evita manipular lesiones.|Usa productos recomendados que no irriten tu piel.|Observa sequedad y tolerancia al plan.", "Solicita evaluación si hay nódulos, cicatrices o gran impacto emocional.|Los antibióticos y retinoides requieren indicación y seguimiento.|Informa cambios hormonales o aparición brusca.", "Confirma cantidad, zona y frecuencia de cada producto.|Algunos tratamientos tienen riesgos importantes en embarazo: consulta antes de usarlos.|No compartas antibióticos o isotretinoína.", "No elimines grupos de alimentos por una promesa de curación.|Si sospechas un patrón, regístralo y revísalo con nutrición.|La alimentación no sustituye un tratamiento indicado.", "No se requiere fisioterapia para acné.|Tras ejercicio, maneja sudor y fricción con higiene suave.|Evita exfoliar intensamente la piel inflamada.", "El acné puede afectar autoestima y vida social.|No minimices el sufrimiento ni culpes por la apariencia.|Pide apoyo si evitas actividades o sientes tristeza persistente."], urgent: "Hinchazón de cara, dificultad respiratoria o reacción cutánea extensa con mal estado tras un tratamiento: urgencias.", contact: "Irritación intensa, cicatrices, empeoramiento o posibilidad de embarazo durante un tratamiento de riesgo.", source: ["Acné", "acne.html"] },
  { parent: "medicina-urgencias", slug: "anafilaxia", focus: "Anafilaxia: actuar sin demora", audience: "Personas con riesgo de reacción alérgica grave y sus cuidadores; una reacción en curso requiere emergencias.", overview: "La anafilaxia puede afectar respiración o circulación y avanzar rápidamente. La adrenalina intramuscular mediante el dispositivo indicado y la activación de emergencias son acciones prioritarias.", education: { signs: "Puede haber hinchazón, ronquera, falta de aire, vómitos o desmayo. Una reacción grave puede ocurrir sin lesiones visibles de piel.", evaluation: "Después de estabilizarse se revisan posibles desencadenantes y el plan de prevención. La mejoría inicial no elimina la necesidad de observación médica.", preparation: "Lleva el autoinyector prescrito, verifica caducidad y enseña su uso con un dispositivo de entrenamiento. No esperes a leer la guía durante una reacción.", followup: "Solicita plan escrito para casa, escuela o trabajo y consulta de alergología. Confirma reposición del dispositivo después de usarlo." }, care: ["Reconoce señales del plan y pide ayuda de emergencia.|No dejes que la persona se levante o camine; posiciónala según respiración y estado.|No des alimentos o líquidos si hay dificultad para tragar.", "Una sospecha de anafilaxia necesita atención inmediata.|Usa el autoinyector indicado sin retrasarlo por esperar más síntomas.|La valoración posterior decide observación y seguimiento.", "Aprende el dispositivo exacto: las instrucciones varían entre marcas.|Los antihistamínicos no sustituyen la adrenalina en anafilaxia.|Confirma con tu equipo el plan si los síntomas persisten.", "Con alergia alimentaria, aprende etiquetas y contaminación cruzada.|No elimines alimentos no implicados sin valoración.|Prepara opciones seguras con nutrición si hay varias alergias.", "Durante la reacción no se hace ejercicio ni se camina para buscar ayuda.|Si el ejercicio es un desencadenante, necesita evaluación especializada.|Retoma actividad solo con un plan de prevención claro.", "Practica el plan con familiares para reducir bloqueo por miedo.|El entrenamiento apoya la acción pero no retrasa emergencias.|Pide apoyo si el temor impide comer o salir de casa."], urgent: "Dificultad respiratoria, hinchazón de lengua o garganta, desmayo o reacción grave tras un alérgeno: usa el autoinyector indicado y llama a emergencias de inmediato.", contact: "Tras atención urgente: revisa desencadenante, plan preventivo y reposición de adrenalina; no esperes a consulta si reaparecen síntomas.", source: ["Anafilaxia", "anaphylaxis.html"] },
  { parent: "laboratorio-clinico", slug: "muestra-orina", focus: "Análisis y recolección de orina", audience: "Personas con análisis de orina solicitado; una muestra simple no se recoge igual que una de 24 horas.", overview: "El análisis busca sustancias y células que orientan sobre vías urinarias y otros problemas. La calidad de la muestra y el contexto clínico son esenciales para interpretar el resultado.", education: { signs: "Se solicita por síntomas o seguimiento. Color u olor aislados no bastan para diagnosticar infección o enfermedad renal.", evaluation: "El equipo puede pedir tira, sedimento, cultivo u otra prueba. Confirma exactamente qué muestra necesita el laboratorio.", preparation: "Usa recipiente indicado, evita tocar su interior y aprende recolección de chorro medio si corresponde. Confirma entrega, conservación y etiquetado.", followup: "Informa menstruación, dificultades o contaminación de la muestra. Pregunta quién interpreta los hallazgos y si es necesario repetirla." }, care: ["Solicita demostración de higiene y recolección adecuada.|No toques el interior del recipiente o tapa.|Consulta ayuda para personas con movilidad limitada o sonda.", "Aclara el propósito del análisis y si incluye cultivo.|Un resultado se interpreta con síntomas y antecedentes.|No concluyas infección solo por bacterias reportadas.", "Informa antibióticos y fármacos que cambian color o resultados.|No suspendas tratamientos para mejorar la muestra.|Si se pidió cultivo antes de antibiótico, sigue el plan sin retrasar una urgencia.", "No bebas agua en exceso para producir una muestra rápidamente.|Confirma ayuno o primera orina solo si la prueba lo requiere.|Respeta restricciones de líquidos que ya tengas.", "No se requiere ejercicio terapéutico para la recolección.|Pide apoyo y un baño accesible si tienes dificultad para desplazarte.|Consulta si debes evitar esfuerzo intenso antes de tu prueba concreta.", "Solicita privacidad y explica cualquier dificultad sin vergüenza.|En niños, usa explicaciones simples sin presionar.|Un resultado aislado no debe interpretarse como diagnóstico definitivo."], urgent: "Fiebre con dolor de costado, incapacidad para orinar o mal estado importante: busca atención, no esperes solo el resultado.", contact: "Muestra derramada o contaminada, instrucciones poco claras o resultado pendiente fuera de plazo.", source: ["Análisis de orina", "urinalysis.html"] },
  { parent: "radiologia-imagen", slug: "tomografia", focus: "Tomografía computarizada y contraste", audience: "Personas con TC solicitada; contraste oral, intravenoso y sedación tienen preparaciones diferentes.", overview: "La TC usa rayos X para obtener cortes del cuerpo. El contraste ayuda en algunas preguntas diagnósticas, pero no se usa de la misma forma en todos los estudios.", education: { signs: "Puede estudiarse abdomen, tórax, cabeza u otra región. El motivo clínico define el protocolo; no se necesita una TC para cualquier síntoma.", evaluation: "Se revisa necesidad del contraste y, cuando corresponde, función renal y antecedentes de reacciones. Informa embarazo posible.", preparation: "Pide instrucciones específicas de alimentos, líquidos y medicamentos. Describe cualquier reacción previa con el nombre del producto si lo conoces.", followup: "Si hubo contraste, pregunta por cuidados individuales y signos de reacción. Confirma cómo recibir el informe y quién lo explicará." }, care: ["Informa alergias, embarazo, función renal y accesos difíciles.|Comunica dolor o hinchazón donde se inyecta contraste.|Sigue indicaciones para permanecer quieto o sostener la respiración.", "Pregunta qué información se busca y si se necesita contraste.|No todos los controles requieren repetir imágenes.|La interpretación se vincula con tu historia y otras pruebas.", "Informa metformina y demás tratamientos; cualquier ajuste depende de función renal y protocolo.|No suspendas fármacos por consejos genéricos de internet.|No te automediques para prevenir una reacción.", "El ayuno depende del estudio y de la sedación; confírmalo.|No aumentes líquidos tras contraste si tienes restricción sin preguntar.|Organiza comida y tratamiento de diabetes según instrucciones.", "La prueba no requiere una rutina de rehabilitación.|Avisa limitaciones para acostarte y solicita apoyos.|Si hubo sedación, cumple restricciones de conducción y actividad.", "Expresa claustrofobia o preocupación por radiación antes del estudio.|Conoce cómo comunicar molestias durante el examen.|Pide explicar el resultado, no lo interpretes solo por una imagen."], urgent: "Dificultad respiratoria, hinchazón de lengua o cara, desmayo o reacción grave tras contraste: atención inmediata.", contact: "Dolor o hinchazón creciente en la punción, erupción nueva o dudas sobre preparación.", source: ["Tomografía computarizada", "ctscans.html"] },
  { parent: "anatomia-patologica", slug: "biopsia-piel", focus: "Biopsia de piel", audience: "Personas con toma de muestra de una lesión cutánea indicada o reciente.", overview: "Se retira una pequeña porción de piel para examinarla. Puede investigar inflamación, infección o cáncer; pedir una biopsia no significa que ya exista un diagnóstico maligno.", education: { signs: "La lesión que se estudia puede tener distintas apariencias. El equipo decide si conviene raspado, sacabocados o extirpación.", evaluation: "Pregunta qué muestra se tomará y si necesitará puntos. La ubicación y el tamaño influyen en el cuidado posterior.", preparation: "Informa alergias a anestesia o adhesivos y tratamientos que afecten sangrado. No suspendas anticoagulantes sin autorización.", followup: "Obtén por escrito cuidado del apósito, limpieza, retiro de puntos si aplica y comunicación del resultado." }, care: ["Aprende limpieza y cobertura según tu tipo de cierre.|No arranques costras o pegamento de piel.|Vigila dolor creciente, calor, enrojecimiento y secreción.", "Pregunta qué diagnósticos se investigan y los posibles siguientes pasos.|Una biopsia puede requerir estudios adicionales.|Confirma cómo te avisarán si hay que ampliar una extirpación.", "Revisa analgesia permitida y productos tópicos.|No apliques antibióticos, alcohol o cremas no indicadas.|Informa antecedentes de reacción a anestésicos o apósitos.", "Por una biopsia superficial no se impone dieta especial de rutina.|Si hay sedación u otro procedimiento, confirma sus reglas.|Mantén ingesta suficiente si existe una herida amplia.", "Evita roce o tensión que pueda abrir la herida.|Pregunta por ejercicio según localización y puntos.|No masajees la cicatriz antes de que el equipo autorice.", "Planifica cómo recibir resultados y expresar dudas.|No asumas el resultado por el aspecto de la lesión.|Solicita apoyo si la espera altera mucho sueño o vida diaria."], urgent: "Sangrado que no cede con presión indicada, reacción respiratoria o mal estado importante: atención urgente.", contact: "Fiebre, secreción, herida abierta o resultado que no llega en el plazo informado.", source: ["Biopsia de piel", "pruebas-de-laboratorio/biopsia-de-piel/"] },
  { parent: "medicina-nuclear", slug: "pet-tc", focus: "PET/TC: preparación y seguimiento", audience: "Personas con PET o PET/TC solicitada; la preparación depende del trazador y del objetivo.", overview: "La PET muestra actividad de tejidos mediante un radiofármaco y puede combinarse con TC. Una zona de captación no equivale automáticamente a cáncer.", education: { signs: "El estudio puede evaluar respuesta de un tratamiento, extensión de una enfermedad u otras preguntas. No se usa de igual forma para todas las personas.", evaluation: "El servicio revisa indicación, glucosa cuando corresponde y seguridad del trazador o contraste de TC. Informa embarazo y lactancia.", preparation: "Confirma ayuno, ejercicio previo, tiempos de espera y manejo individual de diabetes. No ajustes insulina por iniciativa propia.", followup: "Pide indicaciones propias del trazador sobre líquidos, lactancia y contacto cercano. El especialista interpreta junto con antecedentes e imágenes previas." }, care: ["Llega con instrucciones revisadas y comunica si no pudiste cumplirlas.|Permanece en reposo o quieto cuando lo indiquen para evitar interferencias.|Informa dolor o cambios en la zona de inyección.", "Pregunta qué trazador usarán y qué información se busca.|La interpretación distingue actividad tumoral de otras causas posibles.|Confirma quién integrará PET y TC con tus otros estudios.", "Revisa antes de la cita insulina y demás fármacos con el servicio.|No cambies una dosis solo porque escuchaste que hay que ayunar.|Informa medicamentos y tratamientos recientes.", "Sigue la preparación de alimentos y bebidas de tu protocolo.|Los líquidos posteriores deben respetar tu situación cardíaca o renal.|No impongas un ayuno más largo del indicado.", "Confirma si debes evitar ejercicio antes de tu PET específica.|No necesitas rehabilitación por el estudio en sí.|Pide apoyo de postura si el dolor dificulta permanecer quieto.", "Explica si te angustian el espacio o los resultados.|Conoce cómo comunicarte durante el estudio.|No interpretes captaciones por tu cuenta antes del informe."], urgent: "Dificultad para respirar, hinchazón facial o desmayo después del trazador o contraste: atención inmediata.", contact: "Dudas de preparación, glucosa, embarazo o lactancia: consulta antes de recibir el radiofármaco.", source: ["Tomografía por emisión de positrones", "pruebas-de-laboratorio/tomografia-por-emision-de-positrones/"] },
  { parent: "genetica-medica", slug: "brca", focus: "Pruebas BRCA1 y BRCA2", audience: "Personas con indicación de asesoramiento por riesgo hereditario de cáncer y sus familias.", overview: "Los genes BRCA participan en reparación del ADN. Algunas variantes heredadas aumentan riesgo de ciertos cánceres, pero un resultado no significa que el cáncer sea inevitable.", education: { signs: "La indicación depende de antecedentes personales y familiares y otros factores. No se define solo por ansiedad o una prueba comercial.", evaluation: "El asesoramiento explica resultado positivo, negativo o incierto. Una variante de significado incierto no se maneja igual que una variante patogénica.", preparation: "Antes de consentir, pregunta qué prueba se realizará, posibles hallazgos, privacidad y repercusiones familiares.", followup: "Las estrategias de vigilancia o reducción de riesgo se deciden con especialistas. Un resultado incierto puede requerir reinterpretación futura, no cirugía automática." }, care: ["Organiza antecedentes familiares que conozcas respetando privacidad.|Sigue las indicaciones de muestra de sangre o saliva.|Pide un resumen comprensible del resultado.", "Distingue prueba de riesgo hereditario de diagnóstico actual de cáncer.|Revisa vigilancia y opciones preventivas según resultado y contexto.|No tomes decisiones irreversibles con un resultado incierto sin asesoramiento.", "Un resultado genético no permite iniciar fármacos preventivos por tu cuenta.|Si se propone medicación, revisa beneficios, riesgos e interacciones.|Informa tratamientos de cáncer previos o actuales.", "No existe un alimento que cambie una variante BRCA.|Mantén hábitos de salud y evita suplementos con promesas de reparación genética.|Nutrición se adapta a necesidades reales, no a dietas comerciales de ADN.", "El resultado por sí solo no limita actividad ni requiere fisioterapia.|Si se decide cirugía preventiva, habrá una guía de recuperación específica.|Mantén movimiento saludable según tu condición clínica.", "Explora cómo compartir información con familiares sin presión.|La decisión de conocer resultados es personal y necesita apoyo informado.|Solicita ayuda si hay culpa, temor o conflicto familiar."], urgent: "La prueba BRCA no responde a síntomas agudos. Ante una urgencia busca atención sin esperar el resultado.", contact: "Dudas sobre variante incierta, vigilancia, privacidad o comunicación familiar.", source: ["Pruebas genéticas", "genetictesting.html"], extra: [{title: "Cambios en el gen BRCA: el riesgo de cáncer y las pruebas genéticas", organization: "Instituto Nacional del Cáncer (NCI)", url: "https://www.cancer.gov/espanol/cancer/causas-prevencion/genetica/hoja-informativa-brca"}] },
  { parent: "neurofisiologia", slug: "electroencefalograma", focus: "Electroencefalograma (EEG)", audience: "Personas con EEG indicado; estudio de rutina, sueño y monitorización prolongada tienen preparaciones distintas.", overview: "Los electrodos del cuero cabelludo registran señales eléctricas cerebrales. El EEG no mide inteligencia ni introduce electricidad en el cerebro.", education: { signs: "Puede solicitarse por crisis, episodios de desconexión u otras preguntas. Un EEG normal no descarta por sí solo todos los trastornos.", evaluation: "El especialista interpreta patrones junto con síntomas y tratamientos. Algunos estudios incluyen video o registro prolongado.", preparation: "Confirma lavado de cabello, productos a evitar, cafeína y sueño. No hagas privación de sueño si no fue solicitada.", followup: "Pregunta cuándo retomar rutina si dormiste poco o recibiste sedación y quién explicará los resultados." }, care: ["Acude con el cabello preparado según instrucciones.|Informa heridas en cuero cabelludo y antecedentes de crisis.|Comunica cualquier síntoma durante luces o respiración guiada.", "Pregunta qué tipo de EEG recibirás y su objetivo.|La activación se realiza bajo supervisión del personal.|No reproduzcas hiperventilación o luces en casa para provocar síntomas.", "Lleva lista de fármacos y no suspendas antiepilépticos sin orden.|Confirma si se usará sedación.|No tomes productos para dormir o mantenerte despierto por iniciativa propia.", "Consulta indicaciones de cafeína, comidas y ayuno de tu estudio.|No ayunes sin necesidad.|Coordina diabetes y tratamiento si hay preparación especial.", "No se necesita rehabilitación para colocar electrodos.|Si hubo privación de sueño, organiza traslado seguro y evita conducir si estás somnoliento.|Retoma actividades según estado y recomendaciones.", "Pide explicar la colocación y cómo avisar molestias.|En niños, utiliza juego y lenguaje sencillo.|El resultado no define capacidades personales ni valor intelectual."], urgent: "Convulsión prolongada, crisis repetidas sin recuperación o dificultad respiratoria: emergencias según tu plan.", contact: "Dudas sobre sueño, fármacos o preparación: consulta al centro antes de la cita.", source: ["Electroencefalograma", "ency/article/003931.htm"] },
]

export function createAdditionalGuides(base: CareGuide[], ids: readonly DisciplineId[]): CareGuide[] {
  return additionalTopics.map(topic => {
    const parent = base.find(item => item.slug === topic.parent)
    if (!parent) throw new Error(`Especialidad no encontrada: ${topic.parent}`)
    return { ...parent, specialtySlug: parent.slug, slug: topic.slug, focus: topic.focus, overview: topic.overview, audience: topic.audience,
      recommendations: Object.fromEntries(ids.map((id, i) => [id, topic.care[i].split("|")])) as Record<DisciplineId, string[]>,
      urgent: topic.urgent, contact: topic.contact, takeaways: ["Comprendo mi tema: " + topic.focus + ".", "Conozco las señales de alarma y el contacto de mi equipo.", "Tengo por escrito mi preparación, cuidados y próxima revisión."],
      references: [{ title: topic.source[0], organization: "Biblioteca Nacional de Medicina de EE. UU. · MedlinePlus en español", url: `https://medlineplus.gov/spanish/${topic.source[1]}` }, ...(topic.extra ?? []), ...(supplementalReferences[topic.slug] ?? [])], education: topic.education,
    }
  })
}

